function traverse(root, order) {
  const out = [] //@init
  function visit(node) {
    if (!node) return //@base
    if (order === 'pre') out.push(node.val) //@pre
    visit(node.left) //@left
    if (order === 'in') out.push(node.val) //@in
    visit(node.right) //@right
    if (order === 'post') out.push(node.val) //@post
  }
  visit(root) //@start
  return out //@done
}

