type TreeNode = { val: number; left: TreeNode | null; right: TreeNode | null }

function pathSums(root: TreeNode | null): number[] {
  const out: number[] = []
  const walk = (node: TreeNode | null, total: number): void => {
    if (!node) return
    total += node.val
    if (!node.left && !node.right) out.push(total)
    walk(node.left, total)
    walk(node.right, total)
